condary_trap_keys\":[\"catastrophizing\",\"validation_seeking\"],\"explanation_reveal\":\"after_commit\",\"explanation\":\"Fortune Telling treats an uncertain future as certain. Catastrophizing can exaggerate the consequences of declining. Validation Seeking may make the title and salary dominate the evaluation.\\nRemember: More than one thinking trap can exist in the same situation. The goal is not to label yourself; it is to identify what may be distorting the decision.\"},{\"step_number\":3,\"key\":\"reality_check\",\"prompt\":\"Build your own reality check. Identify the facts, assumptions, evidence for and against your view, and the missing information that could materially change the decision.\",\"tip\":\"Missing information is not evidence. Identify what you would need to know before becoming more certain.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What facts do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What assumptions are you making?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your conclusion?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence challenges it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information is still missing?\"}],\"thinkclear_thinking\":[\"This opportunity exists now.\",\"Future opportunities are unknown.\",\"The decision affects more than career progression.\",\"The practical costs need to be quantified rather than assumed.\"],\"reference_example\":[\"This opportunity exists now.\",\"Future opportunities are unknown.\",\"The decision affects more than career progression.\",\"The practical costs need to be quantified rather than assumed.\"]},{\"step_number\":4,\"key\":\"reframe\",\"prompt\":\"Generate the realistic alternatives available to you. Include at least one option that is not your preferred choice and, where relevant, an option that changes the structure of the decision rather than simply choosing A or B.\",\"insight\":\"A decision can improve when you change the question from “Which option wins?” to “What options, conditions or safeguards could make the decision better?”\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least four other explanations or perspectives that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":4}],\"thinkclear_thinking\":[\"The opportunity may materially accelerate growth.\",\"The role may not be sustainable after relocation.\",\"A different structure or relocation support may change the decision.\",\"Another opportunity may arise later, even if timing is uncertain.\"],\"reference_example\":[\"The opportunity may materially accelerate growth.\",\"The role may not be sustainable after relocation.\",\"A different structure or relocation support may change the decision.\",\"Another opportunity may arise later, even if timing is uncertain.\"]},{\"step_number\":5,\"key\":\"intervention\",\"prompt\":\"What would you do next, and why? If this is a decision rather than an immediate reaction, state what information, negotiation, experiment or safeguard should come before the final commitment.\",\"reminder\":\"There isn\'t always a perfect action. There is usually a reasonable next action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available today, what is the most reasonable next action?\"}],\"thinkclear_thinking\":[\"List the decision factors and identify which require actual information.\",\"Clarify the role, authority, expected outcomes, relocation support and work pattern.\",\"Discuss the household impact before deciding.\"],\"reference_example\":\"List the decision factors and identify which require actual information.\\nClarify the role, authority, expected outcomes, relocation support and work pattern.\\nDiscuss the household impact before deciding.\"},{\"step_number\":6,\"key\":\"internalize\",\"prompt\":\"Complete the sentence: “The judgment principle I want to carry forward is…”\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete the sentence: “Today I learned that…”\"}],\"thinkclear_thinking\":\"I don\'t need certainty about the future to make a good decision; I need clarity about the assumptions driving it.\",\"reference_example\":\"I don\'t need certainty about the future to make a good decision; I need clarity about the assumptions driving it.\"}],\"closing_reflection\":{\"prompt\":\"Which part of a major opportunity are you treating as inevitable rather than uncertain?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional reflection entry — take a moment to reflect on today\'s scenario.\",\"required\":false}}}', `updated_at` = '2026-09-25 16:36:12';

INSERT INTO `foundation_days` (`day_number`, `phase`, `title`, `domain`, `primary_trap`, `secondary_trap`, `content_bundle`, `created_at`, `updated_at`)
VALUES (33, 2, 'The Property Rush', 'Finance', 'Validation Seeking', 'Fortune Telling, Sunk Cost Fallacy', '{\"day\":33,\"phase\":2,\"title\":\"The Property Rush\",\"domain\":\"Finance\",\"mission\":\"A major purchase should be evaluated from the future backward—not the emotion forward.\",\"learning_objective\":\"Generate Alternative Explanations\",\"difficulty\":\"Intermediate–Advanced\",\"emotional_intensity\":\"Moderate\",\"estimated_minutes\":\"5-7\",\"primary_skill\":\"Reframe\",\"primary_trap\":\"Validation Seeking\",\"secondary_trap\":\"Fortune Telling, Sunk Cost Fallacy\",\"secondary_traps\":[\"Fortune Telling\",\"Sunk Cost Fallacy\"],\"guidance_level\":\"Reduced guidance; decision, trade-offs and opportunity cost are central.\",\"interaction_principle\":\"Think → Commit → Defend → Compare → Reflect\",\"scenario_text\":\"You have been planning to buy a home for several years.\\nFriends around you are buying properties.\\nYou find a home you like and the seller says the price may increase soon.\\nYou have enough savings for the down payment, but the purchase would create a large monthly commitment.\\nYou feel that continuing to rent means you are falling behind.\",\"steps\":[{\"step_number\":1,\"key\":\"detect\",\"prompt\":\"Start without looking for the \'right\' answer. Write what you know, what you think it means, and what you are tempted to do.\",\"insight\":\"Facts describe what is known. The story explains what the mind thinks the facts mean.\",\"inputs\":[{\"field_key\":\"facts\",\"prompt\":\"Write only the facts.\",\"multiline\":true},{\"field_key\":\"story\",\"prompt\":\"Now write the story\\/assumptions your mind is creating.\",\"multiline\":true}],\"thinkclear_thinking\":{\"facts\":[\"You have savings for a down payment.\",\"The purchase would create a significant monthly commitment.\",\"People around you are buying homes.\",\"You like a particular property.\",\"The seller has said the price may increase.\"],\"story\":\"If I don\'t buy now, I\'ll miss my chance and everyone else will get ahead.\"},\"reference_example\":\"Fact: You have savings for a down payment. The purchase would create a significant monthly commitment. People around you are buying homes. You like a particular property. The seller has said the price may increase.\\nStory: If I don\'t buy now, I\'ll miss my chance and everyone else will get ahead.\"},{\"step_number\":2,\"key\":\"decode\",\"prompt\":\"Which thinking trap(s) may be influencing your judgment? Select the one you think is primary and note any others.\",\"input_type\":\"single_choice_with_multi_notes\",\"options\":[{\"key\":\"mind_reading\",\"label\":\"Mind Reading\",\"definition\":\"Assuming others\' intentions without evidence.\"},{\"key\":\"fortune_telling\",\"label\":\"Fortune Telling\",\"definition\":\"Treating an unverified prediction as certain.\"},{\"key\":\"emotional_reasoning\",\"label\":\"Emotional Reasoning\",\"definition\":\"Treating a feeling as proof of reality.\"},{\"key\":\"catastrophizing\",\"label\":\"Catastrophizing\",\"definition\":\"Assuming the absolute worst outcome.\"},{\"key\":\"confirmation_bias\",\"label\":\"Confirmation Bias\",\"definition\":\"Only seeing details that confirm the feared story.\"},{\"key\":\"rumination\",\"label\":\"Rumination\",\"definition\":\"Repetitive, circular overthinking of past events.\"},{\"key\":\"all_or_nothing\",\"label\":\"All-or-Nothing Thinking\",\"definition\":\"Treating a minor gap as total failure or framing as either-or.\"},{\"key\":\"validation_seeking\",\"label\":\"Validation Seeking\",\"definition\":\"Allowing external approval to define self-worth or decisions.\"},{\"key\":\"sunk_cost_fallacy\",\"label\":\"Sunk Cost Fallacy\",\"definition\":\"Continuing a path solely because of past unrecoverable investment.\"}],\"correct_option_key\":\"validation_seeking\",\"primary_trap\":\"Validation Seeking\",\"secondary_traps\":[\"Fortune Telling\",\"Sunk Cost Fallacy\"],\"secondary_trap_keys\":[\"fortune_telling\",\"sunk_cost_fallacy\"],\"explanation_reveal\":\"after_commit\",\"explanation\":\"Validation Seeking can turn social comparison into a financial criterion. Fortune Telling assumes prices will move in a particular direction. Sunk Cost may appear if you have already spent heavily searching or planning.\\nRemember: More than one thinking trap can exist in the same situation. The goal is not to label yourself; it is to identify what may be distorting the decision.\"},{\"step_number\":3,\"key\":\"reality_check\",\"prompt\":\"Build your own reality check. Identify the facts, assumptions, evidence for and against your view, and the missing information that could materially change the decision.\",\"tip\":\"Missing information is not evidence. Identify what you would need to know before becoming more certain.\",\"inputs\":[{\"field_key\":\"q1\",\"prompt\":\"1. What facts do you know for certain?\"},{\"field_key\":\"q2\",\"prompt\":\"2. What assumptions are you making?\"},{\"field_key\":\"q3\",\"prompt\":\"3. What evidence supports your conclusion?\"},{\"field_key\":\"q4\",\"prompt\":\"4. What evidence challenges it?\"},{\"field_key\":\"q5\",\"prompt\":\"5. What information is still missing?\"}],\"thinkclear_thinking\":[\"I can afford the down payment, but affordability includes future cash flow.\",\"Other people\'s purchases do not determine my needs.\",\"The seller\'s prediction is not evidence of what will happen.\",\"I need to compare buying with continuing to rent or waiting.\"],\"reference_example\":[\"I can afford the down payment, but affordability includes future cash flow.\",\"Other people\'s purchases do not determine my needs.\",\"The seller\'s prediction is not evidence of what will happen.\",\"I need to compare buying with continuing to rent or waiting.\"]},{\"step_number\":4,\"key\":\"reframe\",\"prompt\":\"Generate the realistic alternatives available to you. Include at least one option that is not your preferred choice and, where relevant, an option that changes the structure of the decision rather than simply choosing A or B.\",\"insight\":\"A decision can improve when you change the question from “Which option wins?” to “What options, conditions or safeguards could make the decision better?”\",\"inputs\":[{\"field_key\":\"alt_explanations\",\"prompt\":\"Write at least four other explanations or perspectives that also fit the facts.\",\"type\":\"multi_entry\",\"min_entries\":4}],\"thinkclear_thinking\":[\"Buying now may fit my long-term plans.\",\"Waiting may preserve flexibility.\",\"A different property may fit better.\",\"Renting may be rational for my current circumstances.\"],\"reference_example\":[\"Buying now may fit my long-term plans.\",\"Waiting may preserve flexibility.\",\"A different property may fit better.\",\"Renting may be rational for my current circumstances.\"]},{\"step_number\":5,\"key\":\"intervention\",\"prompt\":\"What would you do next, and why? If this is a decision rather than an immediate reaction, state what information, negotiation, experiment or safeguard should come before the final commitment.\",\"reminder\":\"There isn\'t always a perfect action. There is usually a reasonable next action based on the evidence available.\",\"inputs\":[{\"field_key\":\"action\",\"prompt\":\"Based on the evidence available today, what is the most reasonable next action?\"}],\"thinkclear_thinking\":[\"Calculate the full future cash-flow impact.\",\"Compare the property with realistic alternatives.\",\"Set a decision rule based on affordability and goals rather than social pressure or urgency.\"],\"reference_example\":\"Calculate the full future cash-flow impact.\\nCompare the property with realistic alternatives.\\nSet a decision rule based on affordability and goals rather than social pressure or urgency.\"},{\"step_number\":6,\"key\":\"internalize\",\"prompt\":\"Complete the sentence: “The judgment principle I want to carry forward is…”\",\"inputs\":[{\"field_key\":\"principle\",\"prompt\":\"Complete the sentence: “Today I learned that…”\"}],\"thinkclear_thinking\":\"A major purchase should solve my problem, not my fear of being behind.\",\"reference_example\":\"A major purchase should solve my problem, not my fear of being behind.\"}],\"closing_reflection\":{\"prompt\":\"Which part of your financial decision comes from your own goals, and which part comes from comparison?\",\"journal_input\":{\"field_key\":\"journal\",\"prompt\":\"Optional reflection entry — take a moment to reflect on today\'s scenario.\",\"required\":false}}}', '2026-09-25 16:36:12', '2026-09-25 16:36:12')
